import { useEffect, useState } from "react";
import { Check, GitCompareArrows, SkipForward, X } from "lucide-react";
import { css, cx } from "../../styled-system/css";
import type {
	PendingResponseComparison,
	ResponseComparisonDecision,
} from "../keating/response-comparison";
import { MarkdownBlock } from "./MarkdownBlock";
import { Spinner } from "./Spinner";

interface ResponseComparisonPanelProps {
	comparison: PendingResponseComparison;
	onChoose: (decision: ResponseComparisonDecision) => Promise<void>;
}

type ResponseChoice = "original" | "alternative";

const optionButtonClass = css({
	display: "inline-flex",
	minHeight: "2.5rem",
	alignItems: "center",
	justifyContent: "center",
	gap: "0.375rem",
	borderRadius: "0.375rem",
	paddingInline: "0.875rem",
	fontSize: "0.75rem",
	fontWeight: 600,
	_disabled: { opacity: 0.6 },
});

export function ResponseComparisonPanel({ comparison, onChoose }: ResponseComparisonPanelProps) {
	const [open, setOpen] = useState(false);
	const [active, setActive] = useState<ResponseChoice>("original");
	const [decision, setDecision] = useState<ResponseComparisonDecision | null>(null);

	useEffect(() => {
		if (!open) return;
		const onKeyDown = (event: KeyboardEvent) => {
			if (event.key === "Escape") setOpen(false);
		};
		window.addEventListener("keydown", onKeyDown);
		return () => window.removeEventListener("keydown", onKeyDown);
	}, [open]);

	const choose = async (next: ResponseComparisonDecision) => {
		if (decision) return;
		setDecision(next);
		try {
			await onChoose(next);
		} finally {
			setDecision(null);
		}
	};

	return (
		<>
			<section
				aria-label="Alternative response available"
				className={css({
					marginInline: "auto",
					marginBottom: "0.625rem",
					width: "100%",
					maxWidth: "56rem",
				})}
			>
				<button
					type="button"
					onClick={() => setOpen(true)}
					className={css({
						display: "flex",
						width: "100%",
						alignItems: "center",
						gap: "0.625rem",
						borderRadius: "0.5rem",
						border: "1px solid var(--border)",
						backgroundColor: "var(--card)",
						paddingInline: "0.75rem",
						paddingBlock: "0.625rem",
						textAlign: "left",
						transition: "background-color 180ms ease-out, border-color 180ms ease-out",
						_hover: { backgroundColor: "var(--accent)", borderColor: "var(--primary)" },
					})}
				>
					<GitCompareArrows size={16} className={css({ flexShrink: 0, color: "var(--primary)" })} />
					<span className={css({ minWidth: 0, flex: 1 })}>
						<span className={css({ display: "block", fontSize: "0.75rem", fontWeight: 650, color: "var(--foreground)" })}>
							Another explanation is ready
						</span>
						<span className={css({ display: "block", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontSize: "11px", color: "var(--muted-foreground)" })}>
							Compare it when you have a moment
						</span>
					</span>
					<span className={css({ flexShrink: 0, fontSize: "0.75rem", fontWeight: 600, color: "var(--primary)" })}>
						Compare
					</span>
				</button>
			</section>

			{open ? (
				<div
					className={css({
						position: "fixed",
						inset: 0,
						zIndex: 60,
						display: "flex",
						alignItems: "stretch",
						justifyContent: "center",
						backgroundColor: "rgb(0 0 0 / 0.58)",
						sm: { alignItems: "center", padding: "1.5rem" },
					})}
					role="dialog"
					aria-modal="true"
					aria-labelledby="response-comparison-title"
					onClick={() => setOpen(false)}
				>
					<div
						className={css({
							display: "flex",
							height: "100dvh",
							width: "100%",
							flexDirection: "column",
							backgroundColor: "var(--background)",
							color: "var(--foreground)",
							sm: {
								height: "min(88dvh, 52rem)",
								maxWidth: "68rem",
								borderRadius: "0.75rem",
								border: "1px solid var(--border)",
							},
						})}
						onClick={(event) => event.stopPropagation()}
					>
						<header className={css({ display: "flex", alignItems: "flex-start", gap: "0.75rem", borderBottom: "1px solid var(--border)", padding: "1rem" })}>
							<GitCompareArrows size={18} className={css({ marginTop: "0.125rem", flexShrink: 0, color: "var(--primary)" })} />
							<div className={css({ minWidth: 0, flex: 1 })}>
								<h2 id="response-comparison-title" className={css({ fontSize: "0.9375rem", fontWeight: 700 })}>
									Which explanation helped more?
								</h2>
								<p className={css({ marginTop: "0.125rem", fontSize: "0.75rem", lineHeight: "1.125rem", color: "var(--muted-foreground)" })}>
									Your choice helps Keating learn how to teach you. It does not change the underlying facts.
								</p>
							</div>
							<button type="button" onClick={() => setOpen(false)} aria-label="Close comparison" className={css({ display: "inline-flex", height: "2rem", width: "2rem", flexShrink: 0, alignItems: "center", justifyContent: "center", borderRadius: "0.375rem", _hover: { backgroundColor: "var(--accent)" } })}>
								<X size={16} />
							</button>
						</header>

						<div className={css({ display: "flex", borderBottom: "1px solid var(--border)", padding: "0.5rem", md: { display: "none" } })}>
							{(["original", "alternative"] as const).map((choice) => (
								<button
									key={choice}
									type="button"
									onClick={() => setActive(choice)}
									className={css({ flex: 1, borderRadius: "0.375rem", paddingBlock: "0.5rem", fontSize: "0.75rem", fontWeight: 600 })}
									style={{ background: active === choice ? "var(--accent)" : "transparent" }}
								>
									{choice === "original" ? "Original" : "Alternative"}
								</button>
							))}
						</div>

						<div className={css({ minHeight: 0, flex: 1, overflowY: "auto", padding: "0.75rem", sm: { padding: "1rem" }, md: { display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: "1rem" } })}>
							<ResponseOption label="Original response" content={comparison.originalResponse} choice="original" active={active} decision={decision} onChoose={choose} />
							<ResponseOption label="Alternative response" content={comparison.alternativeResponse} choice="alternative" active={active} decision={decision} onChoose={choose} />
						</div>

						<footer className={css({ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "0.75rem", borderTop: "1px solid var(--border)", padding: "0.75rem 1rem" })}>
							<button type="button" disabled={Boolean(decision)} onClick={() => void choose("skipped")} className={css({ display: "inline-flex", minHeight: "2.25rem", alignItems: "center", gap: "0.375rem", fontSize: "0.75rem", color: "var(--muted-foreground)", _hover: { color: "var(--foreground)" }, _disabled: { opacity: 0.6 } })}>
								{decision === "skipped" ? <Spinner size={13} /> : <SkipForward size={13} />}
								Skip
							</button>
							<span className={css({ fontSize: "11px", color: "var(--muted-foreground)" })}>Comparisons appear in about 1% of replies</span>
						</footer>
					</div>
				</div>
			) : null}
		</>
	);
}

function ResponseOption({
	label,
	content,
	choice,
	active,
	decision,
	onChoose,
}: {
	label: string;
	content: string;
	choice: ResponseChoice;
	active: ResponseChoice;
	decision: ResponseComparisonDecision | null;
	onChoose: (choice: ResponseChoice) => Promise<void>;
}) {
	return (
		<article
			className={css({
				display: active === choice ? "flex" : "none",
				minHeight: 0,
				flexDirection: "column",
				gap: "0.75rem",
				md: { display: "flex" },
			})}
		>
			<h3 className={css({ fontSize: "0.75rem", fontWeight: 700, color: "var(--muted-foreground)" })}>{label}</h3>
			<div className={css({ minHeight: 0, flex: 1, overflowWrap: "anywhere", borderRadius: "0.5rem", backgroundColor: "color-mix(in srgb, var(--muted) 42%, transparent)", padding: "0.875rem", fontSize: "0.875rem", lineHeight: "1.5rem" })}>
				<MarkdownBlock content={content} />
			</div>
			<button
				type="button"
				disabled={Boolean(decision)}
				onClick={() => void onChoose(choice)}
				className={cx(
					optionButtonClass,
					choice === "alternative"
						? css({ backgroundColor: "var(--primary)", color: "var(--primary-foreground)", _hover: { backgroundColor: "color-mix(in srgb, var(--primary) 88%, black)" } })
						: css({ border: "1px solid var(--border)", _hover: { backgroundColor: "var(--accent)" } }),
				)}
			>
				{decision === choice ? <Spinner size={14} /> : <Check size={14} />}
				Choose {choice}
			</button>
		</article>
	);
}

import { DEFAULT_IMAGE_GENERATOR_ID, isImageGeneratorId, type ImageGeneratorId } from "../lib/image-generators";
export {
	addCustomModel,
	addRecentModel,
	getRecentModels,
	loadModelPrefs,
	removeCustomModel,
	type SavedModel,
	subscribeModelPrefs,
	toggleProviderVisibility,
} from "./model-prefs";

export type ReasoningLevel = "off" | "minimal" | "low" | "medium" | "high" | "xhigh";
export type AnimationRenderer = "hyperframes";
export type UiFontFamily = "roboto" | "space-mono" | "jetbrains-mono";
export type ShareLinkMode = "portable-short" | "compressed-hash" | "local-short";

export interface KeatingUiSettings {
	showToolUi: boolean;
	autoOpenArtifacts: boolean;
	showRawErrors: boolean;
	reasoningLevel: ReasoningLevel;
	animationRenderer: AnimationRenderer;
	fontFamily: UiFontFamily;
	shareLinkMode: ShareLinkMode;
	shareWarningAcknowledged: boolean;
	alternativeResponseChance: number;
	userProfileImage: string | null;
	imageGenerator: ImageGeneratorId;
	imageModel: string;
	imageSize: string;
	imageQuality: string;
	localImageBaseUrl: string;
	webSearch: "auto" | "off";
	flashcardSoundEnabled: boolean;
}

export const DEFAULT_UI_SETTINGS: KeatingUiSettings = {
	showToolUi: true,
	autoOpenArtifacts: true,
	showRawErrors: false,
	reasoningLevel: "medium",
	animationRenderer: "hyperframes",
	fontFamily: "jetbrains-mono",
	shareLinkMode: "portable-short",
	shareWarningAcknowledged: false,
	alternativeResponseChance: 0.01,
	userProfileImage: null,
	imageGenerator: DEFAULT_IMAGE_GENERATOR_ID,
	imageModel: "",
	imageSize: "",
	imageQuality: "",
	localImageBaseUrl: "",
	webSearch: "auto",
	flashcardSoundEnabled: false,
};

type FontStack = {
	sans: string;
	serif: string;
	mono: string;
};

const FONT_STACKS: Record<UiFontFamily, FontStack> = {
	roboto: {
		sans: '"Roboto", "Segoe UI", Arial, sans-serif',
		serif: 'Georgia, Cambria, "Times New Roman", Times, serif',
		mono: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
	},
	"space-mono": {
		sans: '"Space Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
		serif: '"Space Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
		mono: '"Space Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
	},
	"jetbrains-mono": {
		sans: '"JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
		serif: '"JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
		mono: '"JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
	},
};

const STORAGE_KEY = "keating_ui_settings";
const UI_SETTINGS_SCHEMA_VERSION = 3;
const SETTINGS_CHANGED_EVENT = "keating:ui-settings-changed";
type LegacyGroundingKey = `${"google"}${"Grounding"}`;
const LEGACY_GOOGLE_GROUNDING_KEY = ("google" + "Grounding") as LegacyGroundingKey;

export const FONT_FAMILY_OPTIONS: Array<{
	value: UiFontFamily;
	label: string;
	description: string;
}> = [
	{
		value: "roboto",
		label: "Roboto",
		description: "Clean sans serif default for the app UI.",
	},
	{
		value: "space-mono",
		label: "Space Mono",
		description: "Retro monospace styling for the entire app.",
	},
	{
		value: "jetbrains-mono",
		label: "JetBrains Mono",
		description: "Terminal monospace matching the Keating brand reference.",
	},
];

export const SHARE_LINK_MODE_OPTIONS: Array<{
	value: ShareLinkMode;
	label: string;
	description: string;
	public: boolean;
}> = [
	{
		value: "portable-short",
		label: "Portable short",
		description: "Short links that work across browsers when share storage is available.",
		public: true,
	},
	{
		value: "compressed-hash",
		label: "Compressed snapshot",
		description: "Embeds the session snapshot in the URL for server-free sharing.",
		public: true,
	},
	{
		value: "local-short",
		label: "Local short",
		description: "Shortest links, available from this browser's cache only.",
		public: false,
	},
];

function normalizeShareLinkMode(value: unknown): ShareLinkMode {
	return value === "compressed-hash" || value === "local-short" || value === "portable-short"
		? value
		: DEFAULT_UI_SETTINGS.shareLinkMode;
}

// Modes that make the session readable by anyone who receives the link. Both
// `portable-short` (session uploaded to the share server) and `compressed-hash`
// (session snapshot embedded in the URL) expose the transcript publicly. Only
// `local-short` keeps the data in this browser's cache, so it is not publicly
// resolvable by a recipient.
export function shareModeExposesDataPublicly(mode: ShareLinkMode): boolean {
	return mode === "portable-short" || mode === "compressed-hash";
}

function normalizeAlternativeResponseChance(value: unknown): number {
	const numeric = typeof value === "number" ? value : Number(value);
	if (!Number.isFinite(numeric)) return DEFAULT_UI_SETTINGS.alternativeResponseChance;
	return Math.max(0, Math.min(1, numeric));
}

type LegacyUiSettingsInput = Partial<KeatingUiSettings>
	& Partial<Record<LegacyGroundingKey, "auto" | "off">>
	& { schemaVersion?: number };

function normalizeSettings(value: LegacyUiSettingsInput | null): KeatingUiSettings {
	const webSearch =
		value?.webSearch === "off" || (value?.webSearch === undefined && value?.[LEGACY_GOOGLE_GROUNDING_KEY] === "off")
			? "off"
			: DEFAULT_UI_SETTINGS.webSearch;

	return {
		showToolUi: value?.showToolUi ?? DEFAULT_UI_SETTINGS.showToolUi,
		autoOpenArtifacts: value?.autoOpenArtifacts ?? DEFAULT_UI_SETTINGS.autoOpenArtifacts,
		showRawErrors: value?.showRawErrors ?? DEFAULT_UI_SETTINGS.showRawErrors,
		reasoningLevel: value?.reasoningLevel ?? DEFAULT_UI_SETTINGS.reasoningLevel,
		animationRenderer: "hyperframes",
		fontFamily:
			value?.fontFamily === "space-mono" || value?.fontFamily === "roboto" || value?.fontFamily === "jetbrains-mono"
				? value.fontFamily
				: DEFAULT_UI_SETTINGS.fontFamily,
		shareLinkMode: normalizeShareLinkMode(value?.shareLinkMode),
		shareWarningAcknowledged: value?.shareWarningAcknowledged === true,
		// Older builds shipped either 5% or 0% as automatic defaults. Version 3
		// makes comparisons deliberately rare at 1%, while preserving every other
		// explicitly chosen probability.
		alternativeResponseChance:
			value?.schemaVersion !== UI_SETTINGS_SCHEMA_VERSION
				&& (value?.alternativeResponseChance === 0.05 || value?.alternativeResponseChance === 0)
				? DEFAULT_UI_SETTINGS.alternativeResponseChance
				: normalizeAlternativeResponseChance(value?.alternativeResponseChance),
		userProfileImage: typeof value?.userProfileImage === "string" && value.userProfileImage.startsWith("data:image/") ? value.userProfileImage : DEFAULT_UI_SETTINGS.userProfileImage,
		imageGenerator: isImageGeneratorId(value?.imageGenerator) ? value.imageGenerator : DEFAULT_UI_SETTINGS.imageGenerator,
		imageModel: typeof value?.imageModel === "string" ? value.imageModel : DEFAULT_UI_SETTINGS.imageModel,
		imageSize: typeof value?.imageSize === "string" ? value.imageSize : DEFAULT_UI_SETTINGS.imageSize,
		imageQuality: typeof value?.imageQuality === "string" ? value.imageQuality : DEFAULT_UI_SETTINGS.imageQuality,
		localImageBaseUrl: typeof value?.localImageBaseUrl === "string" ? value.localImageBaseUrl : DEFAULT_UI_SETTINGS.localImageBaseUrl,
		webSearch,
		flashcardSoundEnabled: value?.flashcardSoundEnabled === true,
	};
}

export function applyKeatingUiTypography(fontFamily: UiFontFamily) {
	if (typeof document === "undefined") return;
	const stacks = FONT_STACKS[fontFamily] ?? FONT_STACKS.roboto;
	const root = document.documentElement;
	root.style.setProperty("--font-sans", stacks.sans);
	root.style.setProperty("--font-serif", stacks.serif);
	root.style.setProperty("--font-mono", stacks.mono);
}

export function loadKeatingUiSettings(): KeatingUiSettings {
	if (typeof localStorage === "undefined") return DEFAULT_UI_SETTINGS;
	try {
		const raw = localStorage.getItem(STORAGE_KEY);
		if (!raw) return DEFAULT_UI_SETTINGS;
		return normalizeSettings(JSON.parse(raw) as LegacyUiSettingsInput);
	} catch (error) {
		console.warn("Failed to load Keating UI settings:", error);
		return DEFAULT_UI_SETTINGS;
	}
}

export function saveKeatingUiSettings(next: KeatingUiSettings) {
	const normalized = normalizeSettings(next);
	try {
		localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...normalized, schemaVersion: UI_SETTINGS_SCHEMA_VERSION }));
	} catch (error) {
		console.warn("Failed to save Keating UI settings:", error);
	}
	window.dispatchEvent(new CustomEvent<KeatingUiSettings>(SETTINGS_CHANGED_EVENT, { detail: normalized }));
}

export function subscribeKeatingUiSettings(callback: (settings: KeatingUiSettings) => void) {
	const notify = () => callback(loadKeatingUiSettings());
	const onCustom = (event: Event) => {
		callback((event as CustomEvent<KeatingUiSettings>).detail ?? loadKeatingUiSettings());
	};
	window.addEventListener(SETTINGS_CHANGED_EVENT, onCustom);
	window.addEventListener("storage", notify);
	return () => {
		window.removeEventListener(SETTINGS_CHANGED_EVENT, onCustom);
		window.removeEventListener("storage", notify);
	};
}

