function toolAliases(name: string): string[] {
	const trimmed = name.trim();
	const withoutNamespace = trimmed.split(/[.:/]/).at(-1) ?? trimmed;
	const withoutFunctionPrefix = trimmed.replace(/^(?:functions?|tools?)_/, "");

